import os

def read_lines(path):
    with open(path, "r") as f:
        for line in f:
            yield line.rstrip("\n")

def filter_nonempty(lines):
    for line in lines:
        if line.strip():
            yield line

def parse_csv_rows(lines, delimiter=","):
    for line in lines:
        fields = [f.strip() for f in line.split(delimiter)]
        if len(fields) >= 2:
            yield {"key": fields[0], "value": fields[1]}

def build_pipeline(path):
    lines = read_lines(path)
    nonempty = filter_nonempty(lines)
    records = parse_csv_rows(nonempty)
    return records

if os.path.exists("data.csv"):
    for record in build_pipeline("data.csv"):
        print(f"{record['key']}: {record['value']}")

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self._capacity = capacity
        self._cache = OrderedDict()

    def get(self, key):
        if key not in self._cache:
            return None
        self._cache.move_to_end(key)
        return self._cache[key]

    def put(self, key, value):
        if key in self._cache:
            self._cache.move_to_end(key)
            self._cache[key] = value
        else:
            if len(self._cache) >= self._capacity:
                self._cache.popitem(last=False)
            self._cache[key] = value

    def __contains__(self, key):
        return key in self._cache

    def __repr__(self):
        items = ", ".join(f"{k}={v}" for k, v in self._cache.items())
        return f"LRUCache({items})"

