from dataclasses import dataclass, field

@dataclass
class TimingResult:
    label: str
    elapsed: float = 0.0
    children: list["TimingResult"] = field(default_factory=list)

_stack: list[TimingResult] = []

@contextmanager
def timed(label: str) -> Generator[TimingResult, None, None]:
    result = TimingResult(label=label)
    if _stack:
        _stack[-1].children.append(result)
    _stack.append(result)
    start = time.perf_counter()
    try:
        yield result
    finally:
        result.elapsed = time.perf_counter() - start
        _stack.pop()

def format_timing(result: TimingResult, indent: int = 0) -> str:
    prefix = "  " * indent
    lines = [f"{prefix}{result.label}: {result.elapsed:.4f}s"]
    for child in result.children:
        lines.append(format_timing(child, indent + 1))
    return "\n".join(lines)

from typing import ClassVar

class RegistryMeta(type):
    _registry: ClassVar[dict[str, type]] = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if bases:
            key = namespace.get("registry_key", name.lower())
            mcs._registry[key] = cls
        return cls

    @classmethod
    def get(mcs, key: str):
        if key not in mcs._registry:
            raise KeyError(f"Unknown type: {key!r}")
        return mcs._registry[key]

    @classmethod
    def all_keys(mcs) -> list[str]:
        return list(mcs._registry.keys())

class Serializer(metaclass=RegistryMeta):
    def serialize(self, data):
        raise NotImplementedError

class JsonSerializer(Serializer):
    registry_key = "json"

    def serialize(self, data):
        import json
        return json.dumps(data, indent=2)

class CsvSerializer(Serializer):
    registry_key = "csv"

    def serialize(self, data):
        if not data:
            return ""
        headers = list(data[0].keys())
        lines = [",".join(headers)]
        for row in data:
            lines.append(",".join(str(row.get(h, "")) for h in headers))
        return "\n".join(lines)

from typing import Any, Optional

class Validated:
    def __init__(self, min_val: float = float("-inf"), max_val: float = float("inf")):
        self.min_val = min_val
        self.max_val = max_val
        self.attr_name: Optional[str] = None

    def __set_name__(self, owner: type, name: str) -> None:
        self.attr_name = f"_{name}"

    def __get__(self, obj: Any, objtype: type = None) -> Any:
        if obj is None:
            return self
        return getattr(obj, self.attr_name, None)

    def __set__(self, obj: Any, value: float) -> None:
        if not isinstance(value, (int, float)):
            raise TypeError(f"{self.attr_name}: expected number, got {type(value).__name__}")
        if not (self.min_val <= value <= self.max_val):
            raise ValueError(f"{self.attr_name}: {value} not in [{self.min_val}, {self.max_val}]")
        setattr(obj, self.attr_name, value)

