from typing import Protocol, runtime_checkable, Any
import importlib
import os

@runtime_checkable
class Plugin(Protocol):
    name: str
    version: str

    def activate(self, config: dict[str, Any]) -> None: ...
    def deactivate(self) -> None: ...

class PluginManager:
    def __init__(self):
        self._plugins: dict[str, Plugin] = {}

    def load_from_module(self, module_path: str) -> None:
        try:
            module = importlib.import_module(module_path)
        except ImportError as e:
            raise RuntimeError(f"Cannot load module: {module_path}") from e
        for attr_name in dir(module):
            attr = getattr(module, attr_name)
            if isinstance(attr, type) and issubclass(attr, Plugin) and attr is not Plugin:
                instance = attr()
                if isinstance(instance, Plugin):
                    self._plugins[instance.name] = instance

    def activate_all(self, config: dict[str, Any]) -> list[str]:
        activated = []
        for name, plugin in self._plugins.items():
            try:
                plugin.activate(config)
                activated.append(name)
            except Exception as e:
                print(f"Failed to activate {name}: {e}")
        return activated

    def deactivate_all(self) -> None:
        for plugin in self._plugins.values():
            try:
                plugin.deactivate()
            except Exception:
                pass

import ast
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class FunctionInfo:
    name: str
    lineno: int
    args: list[str]
    returns: Optional[str]
    complexity: int = 1
    nested_functions: list["FunctionInfo"] = field(default_factory=list)

class ComplexityVisitor(ast.NodeVisitor):
    def __init__(self):
        self._stack: list[FunctionInfo] = []
        self.functions: list[FunctionInfo] = []

    def _current(self) -> Optional[FunctionInfo]:
        return self._stack[-1] if self._stack else None

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        args = [a.arg for a in node.args.args]
        returns = None
        if node.returns:
            returns = ast.dump(node.returns)
        info = FunctionInfo(
            name=node.name,
            lineno=node.lineno,
            args=args,
            returns=returns,
        )
        parent = self._current()
        if parent:
            parent.nested_functions.append(info)
        else:
            self.functions.append(info)
        self._stack.append(info)
        self.generic_visit(node)
        self._stack.pop()

    def visit_If(self, node: ast.If) -> None:
        current = self._current()
        if current:
            current.complexity += 1
            current.complexity += len(node.orelse) if isinstance(node.orelse, list) and any(
                isinstance(n, ast.If) for n in node.orelse
            ) else 0
        self.generic_visit(node)

    def visit_For(self, node: ast.For) -> None:
        current = self._current()
        if current:
            current.complexity += 1
        self.generic_visit(node)

    def visit_While(self, node: ast.While) -> None:
        current = self._current()
        if current:
            current.complexity += 1
        self.generic_visit(node)

    def visit_ExceptHandler(self, node: ast.ExceptHandler) -> None:
        current = self._current()
        if current:
            current.complexity += 1
        self.generic_visit(node)

def analyze_source(source: str) -> list[FunctionInfo]:
    tree = ast.parse(source)
    visitor = ComplexityVisitor()
    visitor.visit(tree)
    return visitor.functions

def format_report(functions: list[FunctionInfo], indent: int = 0) -> str:
    lines = []
    for fn in functions:
        prefix = "  " * indent
        sig = f"{fn.name}({', '.join(fn.args)})"
        lines.append(f"{prefix}{sig} [line {fn.lineno}, complexity {fn.complexity}]")
        if fn.nested_functions:
            lines.append(format_report(fn.nested_functions, indent + 1))
    return "\n".join(lines)

import inspect
from typing import Any, Callable, TypeVar, get_type_hints
from dataclasses import dataclass, field
from enum import Enum, auto

T = TypeVar("T")

class Lifetime(Enum):
    TRANSIENT = auto()
    SINGLETON = auto()

@dataclass
class Registration:
    factory: Callable[..., Any]
    lifetime: Lifetime
    instance: Any = None

class Container:
    def __init__(self):
        self._registry: dict[type, Registration] = {}
        self._resolving: set[type] = set()

    def register(self, interface: type, factory: Callable[..., Any],
                 lifetime: Lifetime = Lifetime.TRANSIENT) -> None:
        self._registry[interface] = Registration(factory=factory, lifetime=lifetime)

    def register_singleton(self, interface: type, factory: Callable[..., Any]) -> None:
        self.register(interface, factory, Lifetime.SINGLETON)

    def resolve(self, interface: type[T]) -> T:
        if interface not in self._registry:
            raise KeyError(f"No registration for {interface.__name__}")
        reg = self._registry[interface]
        if reg.lifetime == Lifetime.SINGLETON and reg.instance is not None:
            return reg.instance
        if interface in self._resolving:
            cycle = " -> ".join(t.__name__ for t in self._resolving)
            raise RecursionError(f"Circular dependency: {cycle} -> {interface.__name__}")
        self._resolving.add(interface)
        try:
            hints = get_type_hints(reg.factory)
            sig = inspect.signature(reg.factory)
            kwargs = {}
            for param_name, param in sig.parameters.items():
                if param_name == "self":
                    continue
                param_type = hints.get(param_name)
                if param_type and param_type in self._registry:
                    kwargs[param_name] = self.resolve(param_type)
            instance = reg.factory(**kwargs)
            if reg.lifetime == Lifetime.SINGLETON:
                reg.instance = instance
            return instance
        finally:
            self._resolving.discard(interface)

    def create_scope(self) -> "Container":
        child = Container()
        child._registry = {
            k: Registration(factory=v.factory, lifetime=v.lifetime,
                            instance=v.instance if v.lifetime == Lifetime.SINGLETON else None)
            for k, v in self._registry.items()
        }
        return child

from typing import Any, Callable, Awaitable
from dataclasses import dataclass, field
import asyncio

@dataclass
class Request:
    method: str
    path: str
    headers: dict[str, str] = field(default_factory=dict)
    body: bytes = b""
    state: dict[str, Any] = field(default_factory=dict)

@dataclass
class Response:
    status: int = 200
    headers: dict[str, str] = field(default_factory=dict)
    body: bytes = b""

NextFn = Callable[[Request], Awaitable[Response]]
Middleware = Callable[[Request, NextFn], Awaitable[Response]]

class Pipeline:
    def __init__(self):
        self._middlewares: list[Middleware] = []
        self._handler: NextFn | None = None

    def use(self, middleware: Middleware) -> "Pipeline":
        self._middlewares.append(middleware)
        return self

    def set_handler(self, handler: NextFn) -> None:
        self._handler = handler

    def _build_chain(self) -> NextFn:
        if self._handler is None:
            raise RuntimeError("No handler registered")
        chain: NextFn = self._handler
        for mw in reversed(self._middlewares):
            outer_chain = chain
            def make_next(m: Middleware, nxt: NextFn) -> NextFn:
                async def call(req: Request) -> Response:
                    return await m(req, nxt)
                return call
            chain = make_next(mw, outer_chain)
        return chain

    async def handle(self, request: Request) -> Response:
        chain = self._build_chain()
        return await chain(request)

async def logging_middleware(req: Request, next_fn: NextFn) -> Response:
    print(f"-> {req.method} {req.path}")
    resp = await next_fn(req)
    print(f"<- {resp.status}")
    return resp

async def auth_middleware(req: Request, next_fn: NextFn) -> Response:
    token = req.headers.get("authorization", "")
    if not token.startswith("Bearer "):
        return Response(status=401, body=b"Unauthorized")
    req.state["user"] = token[7:]
    return await next_fn(req)

async def default_handler(req: Request) -> Response:
    user = req.state.get("user", "anonymous")
    body = f"Hello, {user}! Path: {req.path}".encode()
    return Response(status=200, body=body)
